create table app_user (enabled boolean not null, created_at TIMESTAMPTZ not null, current_organization_id bigint, id bigint generated by default as identity, updated_at TIMESTAMPTZ not null, system_role varchar(32) not null check (system_role in ('USER','SUPERADMIN')), username varchar(50) not null, email varchar(100) not null, full_name varchar(150) not null, avatar_url TEXT, password_hash varchar(255) not null, primary key (id), constraint uq_app_user_email unique (email));
create table audit_event (actor_user_id bigint not null, created_at TIMESTAMPTZ not null, id bigint generated by default as identity, organization_id bigint not null, target_type varchar(80) not null, action varchar(120) not null, target_id varchar(120), metadata varchar(1000), primary key (id));
create table invitation (created_at TIMESTAMPTZ not null, expires_at TIMESTAMPTZ not null, id bigint generated by default as identity, invited_by_user_id bigint not null, organization_id bigint not null, role_definition_id bigint, updated_at TIMESTAMPTZ not null, role varchar(32) not null check (role in ('OWNER','ADMIN','MEMBER','VIEWER')), status varchar(32) not null check (status in ('PENDING','ACCEPTED','EXPIRED','REVOKED')), token varchar(120) not null, email varchar(200) not null, primary key (id), constraint uq_invitation_token unique (token));
create table model (archived_at TIMESTAMPTZ, created_at TIMESTAMPTZ not null, id bigint generated by default as identity, model_size_bytes bigint, organization_id bigint, updated_at TIMESTAMPTZ not null, updated_by_user_id bigint, user_id bigint not null, name varchar(100) not null, storage_bucket varchar(100), storage_etag varchar(128), storage_object_key varchar(512), file_name varchar(255) not null, specific_type varchar(255) not null, type varchar(255) not null, input_schema jsonb not null, model_file bytea not null, primary key (id), constraint uq_model_name_org unique (name, organization_id));
create table organization (created_at TIMESTAMPTZ not null, created_by_user_id bigint not null, id bigint generated by default as identity, updated_at TIMESTAMPTZ not null, updated_by_user_id bigint, slug varchar(120) not null, name varchar(150) not null, avatar_url varchar(600), description varchar(600), primary key (id), constraint uq_organization_slug unique (slug));
create table organization_membership (created_at TIMESTAMPTZ not null, id bigint generated by default as identity, organization_id bigint not null, role_definition_id bigint, updated_at TIMESTAMPTZ not null, user_id bigint not null, role varchar(32) not null check (role in ('OWNER','ADMIN','MEMBER','VIEWER')), status varchar(32) not null check (status in ('ACTIVE','PENDING','REMOVED')), primary key (id), constraint uq_org_membership_org_user unique (organization_id, user_id));
create table plugin_metadata (created_at TIMESTAMPTZ not null, organization_id bigint not null, size_bytes bigint not null, updated_at TIMESTAMPTZ not null, updated_by_user_id bigint, plugin_type varchar(32) not null, id varchar(64) not null, content_type varchar(120) not null, kind varchar(180), object_key varchar(512) not null, file_name varchar(255) not null, primary key (id));
